	/** 
	 * jumpstart the process by instantiating2 Evidence
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		evidenceId = EvidenceService.getEvidenceInstance()
		.createEvidence( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		EvidenceService.getEvidenceInstance()
				.createEvidence( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.evidenceSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Evidence : " + successValue.getEvidenceId());
							  if (successValue.getEvidenceId().equals(evidenceId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfEvidenceList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Evidence test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on evidence consumed")
					);
			subscriber.evidenceSubscribe( evidenceId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Evidence : " + successValue.getEvidenceId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfEvidenceList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on evidence for evidenceId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Evidence. 
	 */
	protected Evidence read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Evidence" );

		Evidence entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Evidence with primary key" );
		msg.append( evidenceId );
		
		EvidenceFetchOneSummary fetchOneSummary = new EvidenceFetchOneSummary( evidenceId );

		try {
			entity = EvidenceService.getEvidenceInstance().getEvidence( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Evidence " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Evidence.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Evidence." );

		StringBuilder msg = new StringBuilder( "Failed to update a Evidence : " );        
		Evidence entity = read();
		UpdateEvidenceCommand command = generateUpdateCommand();
		command.setEvidenceId(entity.getEvidenceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Evidence." );

			// for use later on...
			evidenceId = entity.getEvidenceId();

			EvidenceService proxy = EvidenceService.getEvidenceInstance();  

			proxy.updateEvidence( command ).get();

			LOGGER.info( "-- Successfully saved Evidence - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + evidenceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Evidence.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Evidence." );

		Evidence entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Evidence with id " + evidenceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Evidence with id " + evidenceId );

			throw e;
		}

		try{
			EvidenceService.getEvidenceInstance().delete( new DeleteEvidenceCommand( entity.getEvidenceId() ) ).get();
			LOGGER.info( "-- Successfully deleted Evidence with id " + evidenceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Evidence with id " + evidenceId );

			throw e;
		}
	}

	/**
	 * get all Evidences.
	 */
	protected List<Evidence> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Evidences:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Evidence : " );        
		List<Evidence> collection  = new ArrayList<>();

		try {
			// call the static get method on the EvidenceService
			collection = EvidenceService.getEvidenceInstance().getAllEvidence();
			assertNotNull( collection, "An Empty collection of Evidence was incorrectly returned.");
			
			// Now print out the values
			Evidence entity = null;            
			Iterator<Evidence> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getEvidenceId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

